<template>
  <div :class="cn('flex flex-col gap-1.5 relative w-full')">
    <p v-if="label" class="text-sm font-medium">{{ label }}</p>
    <Popover v-model:open="open">
      <PopoverAnchor class="relative">
        <PopoverTrigger as-child>
          <Button
            variant="outline"
            role="combobox"
            :aria-expanded="open"
            :class="cn('w-full h-10 justify-between', !value && 'text-muted-foreground')"
          >
            <span class="inline-flex items-center overflow-hidden">
              <component :is="icon" v-if="icon" class="me-2 h-4 w-4 shrink-0" />
              <span v-if="selectedItem" class="line-clamp-1">
                {{ selectedItem.name ?? selectedItem.value }}
                <span v-if="selectedItem.subtitle" class="text-muted-foreground">
                  &middot; {{ selectedItem.subtitle }}
                </span>
                <!-- Inline rather than a second line: the trigger is a single-line, fixed-height button. -->
                <span v-if="selectedItem.caption" class="text-muted-foreground">
                  &middot; {{ selectedItem.caption }}
                </span>
              </span>
              <span v-else class="line-clamp-1">{{ placeholder }}</span>
            </span>
            <Spinner v-if="loading" class="ml-1 h-4 w-4 shrink-0" />
            <ChevronsUpDownIcon v-else-if="!clearable || !value" class="h-4 w-4 shrink-0" />
            <span v-else class="h-4 w-4 shrink-0" />
          </Button>
        </PopoverTrigger>
        <XIcon
          v-if="clearable && !loading && value"
          class="h-4 w-4 ml-2 shrink-0 absolute right-4 top-[0.75rem] cursor-pointer"
          @click.stop.prevent="onChange(null)"
        />
      </PopoverAnchor>
      <PopoverContent class="w-[var(--reka-popover-trigger-width)] p-0">
        <div v-if="flatItems.length === 0" class="py-6 px-4 text-center text-sm">{{ emptyText }}</div>
        <Command v-else>
          <CommandInput v-if="flatItems.length >= minItemsForSearch" :placeholder="inputPlaceholder" />
          <CommandList
            :class="
              cn(
                'relative z-0',
                flatItems.length >= minItemsForSearch
                  ? 'max-h-[min(20rem,_calc(var(--reka-popover-content-available-height)-50px))]'
                  : 'max-h-[min(20rem,_calc(var(--reka-popover-content-available-height)-10px))]'
              )
            "
          >
            <CommandEmpty>{{ emptyText }}</CommandEmpty>
            <template v-for="(group, groupIndex) in normalizedGroups" :key="groupIndex">
              <CommandSeparator v-if="groupIndex > 0" />
              <CommandGroup>
                <div v-if="group.label" class="pl-8 pr-2 py-1.5 text-xs font-medium text-muted-foreground">
                  {{ group.label }}
                </div>
                <CommandItem
                  v-for="item in group.items"
                  :key="item.name"
                  :value="item.value"
                  :class="cn('cursor-pointer', item.emphasized && 'font-semibold text-primary')"
                  @select="onChange(item.value)"
                >
                  <CheckIcon :class="cn('mr-2 h-4 w-4', value && value === item.value ? 'opacity-100' : 'opacity-0')" />
                  <img v-if="item.iconSrc" :src="item.iconSrc" alt="" class="h-5 w-5 shrink-0 object-contain" />
                  <span class="flex min-w-0 flex-col">
                    <span class="truncate">
                      {{ item.name }}
                      <span v-if="item.subtitle" class="text-muted-foreground">&middot; {{ item.subtitle }}</span>
                    </span>
                    <span v-if="item.caption" class="truncate text-xs text-muted-foreground">{{ item.caption }}</span>
                  </span>
                </CommandItem>
              </CommandGroup>
            </template>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  </div>
</template>

<script setup lang="ts" generic="T extends string">
import { CheckIcon, ChevronsUpDownIcon, XIcon } from 'lucide-vue-next';
import { cn } from '~/components/ui/utils';
import { FetchError } from 'ofetch';
import { Spinner } from '~/assets/icons';
import { type AcceptableValue, PopoverAnchor } from 'reka-ui';

interface Props {
  label?: string;
  items?: SelectItem<T>[];
  /** Grouped options: each group is separated by a divider and can have an optional heading. Wins over `items`. */
  groups?: SelectItemGroup<T>[];
  value: T | null;
  placeholder: string;
  inputPlaceholder?: string;
  propertyName: string;
  emptyText: string;
  error?: FetchError | string | null;
  nullIsAll: boolean;
  loading?: boolean;
  minItemsForSearch?: number;
  icon?: any;
  clearable?: boolean;
  isFirstPageOnly?: boolean;
}

const props = withDefaults(defineProps<Props>(), {
  placeholder: undefined,
  inputPlaceholder: undefined,
  emptyText: 'No items found.',
  error: undefined,
  label: undefined,
  loading: false,
  minItemsForSearch: 10,
  icon: undefined,
  clearable: true,
  isFirstPageOnly: true,
  items: () => [],
  groups: undefined,
});

const emit = defineEmits(['change']);

const open = ref(false);

const route = useRoute();

const normalizedGroups = computed<SelectItemGroup<T>[]>(() => props.groups ?? [{ items: props.items }]);

const flatItems = computed(() => normalizedGroups.value.flatMap((group) => group.items));

const allItems = computed(() => {
  if (props.nullIsAll) {
    return [{ name: props.placeholder, value: null }, ...flatItems.value];
  }
  return flatItems.value;
});

const selectedItem = computed(() => {
  return allItems.value.find((item) => item.value === props.value) ?? null;
});

async function onChange(value: AcceptableValue) {
  open.value = false;
  const propertyObject = getPropertyObject(value);
  await navigateTo({
    name: route.name,
    params: route.params,
    query: {
      ...route.query,
      ...(props.isFirstPageOnly ? { page: 1 } : {}),
      ...propertyObject,
    },
  });
  emit('change', value);
}

function getPropertyObject(value: AcceptableValue) {
  value = value as T | null;
  const propertyNames = props.propertyName.split('|');
  const propertyValues = value?.split('|') || [];
  const propertyObject: Record<string, string | undefined> = {};
  propertyNames.forEach((name, index) => {
    propertyObject[name] = propertyValues[index] || undefined;
  });
  return propertyObject;
}
</script>
